INSERT INTO exams (title, description, duration_minutes, pass_percent, max_attempts) VALUES ('HTML Complete Question Bank', 'Tags, forms, tables, semantic HTML, media, accessibility, SEO and interview favourites.', 60, 50, 0);
INSERT INTO exams (title, description, duration_minutes, pass_percent, max_attempts) VALUES ('CSS Complete Question Bank', 'Selectors, specificity, box model, Flexbox, Grid, responsive design, animations and interview favourites.', 70, 50, 0);
INSERT INTO exams (title, description, duration_minutes, pass_percent, max_attempts) VALUES ('JavaScript Complete Question Bank', 'Variables, scope, closures, arrays, async/await, DOM, events, ES6+ and interview favourites.', 70, 50, 0);
INSERT INTO questions (exam_id, question, option_a, option_b, option_c, option_d, correct_option, marks, explanation) VALUES
(1, 'What does HTML stand for?', 'HyperText Making Language', 'Hyperlinks and Text Markup Language', 'HyperText Markup Language', 'Home Tool Markup Language', 'C', 1, 'HTML is the standard markup language that describes the structure of web pages.'),
(1, 'Which declaration tells the browser the page uses HTML5?', '<html version="5">', '<meta html5>', '<!HTML5>', '<!DOCTYPE html>', 'D', 1, 'The short doctype triggers standards mode and is the HTML5 doctype.'),
(1, 'Which element contains all the visible content of a page?', '<meta>', '<body>', '<head>', '<title>', 'B', 1, 'The body holds everything that is displayed in the browser window.'),
(1, 'Where does the <title> element belong?', 'Inside <head>', 'Inside <body>', 'Inside <footer>', 'After </html>', 'A', 1, 'The title is metadata shown in the browser tab, so it lives in the head.'),
(1, 'Which tag creates the largest heading?', '<h1>', '<heading>', '<h6>', '<head>', 'A', 1, 'Headings run from <h1> (largest) to <h6> (smallest).'),
(1, 'Which tag defines a paragraph?', '<para>', '<text>', '<pg>', '<p>', 'D', 1, 'The <p> element is a block-level paragraph.'),
(1, 'Which tag inserts a single line break?', '<nl>', '<break>', '<br>', '<lb>', 'C', 1, '<br> is a void element that forces a line break.'),
(1, 'Which tag draws a horizontal rule (thematic break)?', '<line>', '<hr>', '<rule>', '<hl>', 'B', 1, '<hr> represents a thematic break between content.'),
(1, 'Which attribute of <a> sets the link destination?', 'href', 'link', 'url', 'src', 'A', 1, 'href (hypertext reference) holds the target URL.'),
(1, 'How do you open a link in a new browser tab?', 'new="tab"', 'target="_blank"', 'open="new"', 'window="_new"', 'B', 1, 'target="_blank" opens the link in a new browsing context.'),
(1, 'Which rel value should accompany target="_blank" to prevent reverse tabnabbing?', 'prefetch', 'external', 'noopener', 'nofollow', 'C', 1, 'noopener stops the new page from accessing window.opener.'),
(1, 'Which tag embeds an image?', '<pic>', '<src>', '<image>', '<img>', 'D', 1, '<img> is a void element with a src attribute.'),
(1, 'Which attribute provides alternative text for an image?', 'name', 'caption', 'title', 'alt', 'D', 1, 'alt is read by screen readers and shown if the image fails to load.'),
(1, 'Which of these is a void (self-closing) element?', '<span>', '<div>', '<img>', '<section>', 'C', 1, 'Void elements such as img, br, hr and input have no closing tag.'),
(1, 'Which tag creates an unordered (bulleted) list?', '<ul>', '<dl>', '<ol>', '<list>', 'A', 1, '<ul> renders bullets; <ol> renders numbers.'),
(1, 'Which tag creates a numbered list?', '<nl>', '<ol>', '<num>', '<ul>', 'B', 1, '<ol> is an ordered list.'),
(1, 'Which tag defines an item inside <ul> or <ol>?', '<il>', '<item>', '<li>', '<list-item>', 'C', 1, '<li> stands for list item.'),
(1, 'Which element wraps a description list of terms and definitions?', '<ul>', '<dd>', '<desc>', '<dl>', 'D', 1, '<dl> contains <dt> terms and <dd> descriptions.'),
(1, 'Which tag creates a table?', '<grid>', '<table>', '<tab>', '<tbl>', 'B', 1, '<table> with <tr>, <th> and <td> builds a table.'),
(1, 'Which tag defines a table row?', '<tr>', '<th>', '<row>', '<td>', 'A', 1, '<tr> is a table row.'),
(1, 'What does <th> define?', 'A table row', 'A table footer', 'A table header cell', 'A table title', 'C', 1, '<th> is a header cell, bold and centered by default.'),
(1, 'Which attribute makes a cell span multiple columns?', 'merge', 'colspan', 'rowspan', 'colsize', 'B', 1, 'colspan="2" stretches a cell across two columns.'),
(1, 'Which attribute makes a cell span multiple rows?', 'rowspan', 'rowmerge', 'colspan', 'span-y', 'A', 1, 'rowspan="2" stretches a cell down two rows.'),
(1, 'Which element groups the header rows of a table?', '<tophead>', '<header>', '<th-group>', '<thead>', 'D', 1, '<thead>, <tbody> and <tfoot> group table rows semantically.'),
(1, 'Which element gives a table a title?', '<title>', '<legend>', '<figcaption>', '<caption>', 'D', 1, '<caption> is the first child of <table>.'),
(1, 'Which tag creates an HTML form?', '<submit>', '<form>', '<fields>', '<input-form>', 'B', 1, '<form> wraps controls that send data to a server.'),
(1, 'Which form attribute sets where the data is sent?', 'action', 'target', 'method', 'href', 'A', 1, 'action is the URL that processes the form.'),
(1, 'Which HTTP method puts form data in the URL query string?', 'PATCH', 'PUT', 'GET', 'POST', 'C', 1, 'GET appends data to the URL, so it is visible and bookmarkable.'),
(1, 'Which method should be used to submit a login password?', 'POST', 'GET', 'HEAD', 'OPTIONS', 'A', 1, 'POST sends data in the request body so it does not appear in the URL.'),
(1, 'Which input type hides the characters typed?', 'mask', 'hidden', 'secret', 'password', 'D', 1, 'type="password" masks the input.'),
(1, 'Which input type gives built-in email format validation?', 'mail', 'email', 'text', 'address', 'B', 1, 'type="email" validates a basic email pattern on submit.'),
(1, 'Which attribute makes a form field mandatory?', 'needed', 'mandatory', 'required', 'validate', 'C', 1, 'required blocks submission when the field is empty.'),
(1, 'What is the purpose of the placeholder attribute?', 'Limits the length', 'Shows a hint inside an empty field', 'Makes the field read-only', 'Sets the default submitted value', 'B', 1, 'Placeholder text disappears when the user types.'),
(1, 'Which tag creates a dropdown list?', '<select>', '<list>', '<option-list>', '<dropdown>', 'A', 1, '<select> contains <option> elements.'),
(1, 'Which tag defines an item in a dropdown?', '<item>', '<li>', '<option>', '<choice>', 'C', 1, '<option> sits inside <select> or <datalist>.'),
(1, 'Which tag creates a multi-line text input?', '<textbox>', '<text>', '<input type="multiline">', '<textarea>', 'D', 1, '<textarea> accepts multiple lines of text.'),
(1, 'How do you link a <label> to an input?', 'Put both in the same div', 'Use the same class name', 'Use the same name attribute', 'Match label for to the input id', 'D', 1, 'for="email" connects the label to input id="email" and enlarges the click target.'),
(1, 'Which input type lets the user choose only one option from a group?', 'checkbox', 'radio', 'option', 'select-one', 'B', 1, 'Radio buttons are mutually exclusive within a group.'),
(1, 'What makes radio buttons belong to the same group?', 'The same name attribute', 'The same id', 'The same value', 'The same class', 'A', 1, 'Radios sharing a name allow only one selection.'),
(1, 'Which input type allows selecting multiple independent options?', 'multi', 'toggle', 'checkbox', 'radio', 'C', 1, 'Each checkbox can be checked on its own.');
INSERT INTO questions (exam_id, question, option_a, option_b, option_c, option_d, correct_option, marks, explanation) VALUES
(1, 'What is the default type of a <button> inside a form?', 'none', 'button', 'reset', 'submit', 'D', 1, 'Without a type attribute, a button submits the form.'),
(1, 'Which input type opens a date picker?', 'date', 'datetime-text', 'day', 'calendar', 'A', 1, 'type="date" shows a native date control.'),
(1, 'Which input type is used for file uploads?', 'upload', 'file', 'document', 'attachment', 'B', 1, 'type="file" opens the file chooser.'),
(1, 'Which form attribute is required to upload files?', 'type="file-upload"', 'enctype="text/plain"', 'enctype="multipart/form-data"', 'method="GET"', 'C', 1, 'File uploads need multipart encoding with POST.'),
(1, 'What do <fieldset> and <legend> do?', 'Create a table inside a form', 'Validate the form', 'Hide form fields', 'Group related controls and give the group a caption', 'D', 1, 'They improve structure and accessibility of forms.'),
(1, 'What happens to a field with the disabled attribute on form submit?', 'Its value is sent', 'Its value is not sent', 'The form fails', 'It becomes required', 'B', 1, 'Disabled controls are excluded from submission.'),
(1, 'How does readonly differ from disabled?', 'A readonly field is still submitted', 'A readonly field is not submitted', 'They are identical', 'A readonly field cannot be focused', 'A', 1, 'Readonly fields can be focused and their values are sent.'),
(1, 'Which input attribute restricts the number of characters?', 'size-limit', 'limit', 'maxlength', 'max-char', 'C', 1, 'maxlength caps the characters allowed.'),
(1, 'Which attribute validates input against a regular expression?', 'pattern', 'match', 'validate', 'regex', 'A', 1, 'pattern="[A-Za-z]{3}" is checked by the browser.'),
(1, 'Which attribute pre-selects a checkbox or radio button?', 'active', 'selected', 'default', 'checked', 'D', 1, 'checked sets the initial state of checkboxes and radios.'),
(1, 'Which attribute pre-selects an <option> in a <select>?', 'active', 'selected', 'checked', 'default', 'B', 1, 'selected marks the default option.'),
(1, 'Which input type shows a slider?', 'scale', 'number-range', 'range', 'slider', 'C', 1, 'type="range" with min and max shows a slider.'),
(1, 'Which input type opens a colour picker?', 'palette', 'colour', 'rgb', 'color', 'D', 1, 'type="color" returns a hex value.'),
(1, 'Which attribute focuses a field automatically on page load?', 'autoselect', 'onload', 'autofocus', 'focus', 'C', 1, 'autofocus gives the first matching element focus.'),
(1, 'Which form attribute disables the browser''s built-in validation?', 'noverify', 'novalidate', 'validate="false"', 'disable-validation', 'B', 1, 'novalidate lets you handle validation yourself.'),
(1, 'Which element represents the main navigation links?', '<nav>', '<menu-bar>', '<navigate>', '<links>', 'A', 1, '<nav> is a semantic landmark for navigation.'),
(1, 'Which element is for introductory content or a page heading area?', '<intro>', '<head>', '<top>', '<header>', 'D', 1, '<header> is semantic; <head> is metadata.'),
(1, 'Which element represents footer content like copyright or contact info?', '<foot>', '<bottom>', '<footer>', '<end>', 'C', 1, '<footer> is a semantic landmark.'),
(1, 'How many visible <main> elements should a page have?', 'None', 'One', 'Two', 'As many as needed', 'B', 1, '<main> marks the unique central content of the page.'),
(1, 'Which element holds self-contained content such as a blog post?', '<article>', '<section>', '<div>', '<aside>', 'A', 1, 'An article can be distributed independently.'),
(1, 'Which element groups related content under a heading?', '<section>', '<span>', '<group>', '<b>', 'A', 1, '<section> is a thematic grouping, usually with a heading.'),
(1, 'Which element is meant for sidebars and tangential content?', '<side>', '<aside>', '<margin>', '<sidebar>', 'B', 1, '<aside> holds content related indirectly to the main content.'),
(1, 'Which elements pair an image with its caption?', '<image> and <title>', '<picture> and <label>', '<figure> and <figcaption>', '<img> and <caption>', 'C', 1, 'figure wraps self-contained media; figcaption describes it.'),
(1, 'Why is semantic HTML important?', 'It makes pages load faster in all cases', 'It removes the need for CSS', 'It is required for JavaScript', 'Better accessibility, SEO and readability', 'D', 1, 'Semantic tags describe meaning to browsers, search engines and screen readers.'),
(1, 'What is the main difference between <div> and <span>?', 'div is block-level, span is inline', 'span can contain div but div cannot contain span', 'div is inline, span is block-level', 'Both are block-level', 'A', 1, 'div starts a new line; span flows within text.'),
(1, 'Which element is inline by default?', '<div>', '<span>', '<p>', '<section>', 'B', 1, '<span>, <a> and <strong> are inline.'),
(1, 'Which element is block-level by default?', '<a>', '<em>', '<div>', '<span>', 'C', 1, 'Block elements take the full available width and start on a new line.'),
(1, 'What is the semantic difference between <strong> and <b>?', 'They are identical in meaning', 'strong is deprecated', 'b means importance, strong is only stylistic', 'strong means importance, b is only stylistic', 'D', 1, 'strong carries semantic weight that screen readers can convey.'),
(1, 'Which element represents emphasised text?', '<u>', '<em>', '<emph>', '<i-emphasis>', 'B', 1, '<em> marks stress emphasis and is italic by default.'),
(1, 'Which element highlights text like a marker?', '<highlight>', '<hl>', '<hilite>', '<mark>', 'D', 1, '<mark> shows text with a yellow background by default.'),
(1, 'Which element preserves whitespace and line breaks?', '<format>', '<code>', '<pre>', '<text>', 'C', 1, '<pre> displays text exactly as typed in a monospace font.'),
(1, 'Which element marks a short inline piece of computer code?', '<code>', '<kbd-code>', '<tt-code>', '<script>', 'A', 1, '<code> is the semantic element for code fragments.'),
(1, 'Which element is used for a long quotation from another source?', '<quote-block>', '<cite>', '<q>', '<blockquote>', 'D', 1, '<blockquote> is block-level; <q> is for short inline quotes.'),
(1, 'Which element defines an abbreviation with a tooltip via title?', '<acr-text>', '<short>', '<abbr>', '<abbrev>', 'C', 1, '<abbr title="HyperText Markup Language">HTML</abbr>.'),
(1, 'Which element represents a date or time in machine-readable form?', '<time>', '<clock>', '<datetime>', '<date>', 'A', 1, '<time datetime="2026-11-17"> helps search engines and tools.'),
(1, 'Which attribute shows playback controls on a <video>?', 'show-controls', 'controls', 'player', 'buttons', 'B', 1, 'controls displays play, pause and volume UI.'),
(1, 'Which element lets you offer multiple file formats for <video> or <audio>?', '<format>', '<file>', '<source>', '<track-src>', 'C', 1, 'The browser picks the first format it supports.'),
(1, 'Which element adds subtitles to a video?', '<track>', '<caption>', '<subtitle>', '<text-track>', 'A', 1, '<track kind="subtitles" src="..."> adds timed text.'),
(1, 'Which element embeds another web page inside the current page?', '<frame-set>', '<iframe>', '<embed-page>', '<include>', 'B', 1, '<iframe> creates a nested browsing context.'),
(1, 'Which element draws graphics via JavaScript?', '<paint>', '<graphic>', '<draw>', '<canvas>', 'D', 1, '<canvas> gives a bitmap area controlled by scripts.');
INSERT INTO questions (exam_id, question, option_a, option_b, option_c, option_d, correct_option, marks, explanation) VALUES
(1, 'What is a key advantage of inline <svg> over a bitmap image?', 'It cannot be styled', 'It scales without losing quality', 'It does not need a browser', 'It is always smaller than PNG', 'B', 1, 'SVG is vector-based and can be styled with CSS.'),
(1, 'How long does data in localStorage persist?', 'For 24 hours', 'Until the page reloads', 'Until it is cleared by the user or code', 'Until the tab is closed', 'C', 1, 'localStorage has no automatic expiry.'),
(1, 'How long does sessionStorage data persist?', 'Until the tab or window is closed', 'For 30 days', 'Forever', 'Until the browser updates', 'A', 1, 'sessionStorage is scoped to a single tab session.'),
(1, 'What type of values can localStorage store?', 'Functions', 'Any JavaScript object', 'Numbers only', 'Strings only', 'D', 1, 'Objects must be converted with JSON.stringify.'),
(1, 'What are data-* attributes used for?', 'Storing custom data on elements', 'Styling with CSS only', 'Connecting to databases', 'Loading data files', 'A', 1, 'They are read in JavaScript through element.dataset.'),
(1, 'What does <meta charset="UTF-8"> do?', 'Sets the page language', 'Sets the character encoding', 'Adds a stylesheet', 'Sets the viewport', 'B', 1, 'UTF-8 supports almost every character in every language.'),
(1, 'Why is the viewport meta tag important?', 'It blocks zooming', 'It speeds up the page', 'It makes the page scale properly on mobile screens', 'It adds a mobile menu', 'C', 1, 'width=device-width, initial-scale=1 is the usual responsive setup.'),
(1, 'Which meta tag influences the snippet shown in search results?', '<meta name="snippet">', '<meta name="viewport">', '<meta charset>', '<meta name="description">', 'D', 1, 'Search engines often use the description as the result snippet.'),
(1, 'Which element links an external stylesheet?', '<link rel="stylesheet">', '<script rel="css">', '<css href="">', '<style src="">', 'A', 1, '<link> in the head loads CSS files.'),
(1, 'Which script attribute loads in parallel and runs after the HTML is parsed, in order?', 'preload', 'defer', 'async', 'lazy', 'B', 1, 'defer keeps document order and waits for parsing to finish.'),
(1, 'Which script attribute runs the script as soon as it is downloaded?', 'immediate', 'now', 'defer', 'async', 'D', 1, 'async scripts may run before parsing is finished and in any order.'),
(1, 'What is shown if JavaScript is disabled?', 'Content inside <script>', 'Nothing at all', 'Content inside <noscript>', 'Content inside <template>', 'C', 1, '<noscript> provides fallback content.'),
(1, 'What does the <template> element do?', 'Holds HTML that is not rendered until cloned by JavaScript', 'Loads a theme', 'Creates a CSS template', 'Defines the page layout', 'A', 1, 'Template content is inert until used.'),
(1, 'Which element helps deliver different images for different screens?', '<multi-img>', '<picture>', '<responsive>', '<imgset>', 'B', 1, '<picture> with <source media> enables art direction.'),
(1, 'What does the srcset attribute do?', 'Compresses images', 'Defines a slideshow', 'Sets the alt text', 'Lists image candidates of different sizes or densities', 'D', 1, 'The browser chooses the best image from srcset.'),
(1, 'Which attribute delays loading of offscreen images?', 'async', 'lazy-load', 'loading="lazy"', 'defer', 'C', 1, 'loading="lazy" loads images when they near the viewport.'),
(1, 'Which attribute makes an element editable by the user?', 'editable', 'writable', 'contenteditable', 'edit-mode', 'C', 1, 'contenteditable="true" allows in-place editing.'),
(1, 'Which attribute hides an element from rendering?', 'hidden', 'invisible', 'collapse', 'display', 'A', 1, 'The hidden attribute removes the element from display.'),
(1, 'Which statement about id is correct?', 'id is only for forms', 'An id must be unique in the document', 'An id can be reused many times', 'id is optional in CSS selectors', 'B', 1, 'Use class for reusable styling hooks.'),
(1, 'What does tabindex control?', 'Table columns', 'Browser tabs', 'Tab character size', 'Keyboard focus order', 'D', 1, 'tabindex="0" makes an element focusable; negative values remove it from tab order.'),
(1, 'What does aria-label provide?', 'A tooltip colour', 'A CSS class', 'A form label that is visible', 'An accessible name for assistive technology', 'D', 1, 'aria-label is read by screen readers when no visible text exists.'),
(1, 'What is the role attribute used for?', 'Defining an element''s purpose for assistive technology', 'Setting user roles in a database', 'Styling elements', 'Adding events', 'A', 1, 'role="button" tells assistive tech how to treat an element.'),
(1, 'Why should the lang attribute be set on <html>?', 'It sets the font', 'Screen readers and search engines need the page language', 'It translates the page automatically', 'It is required for CSS', 'B', 1, 'lang="en" improves pronunciation and indexing.'),
(1, 'Which elements create a native collapsible section?', '<collapse> and <title>', '<accordion> and <item>', '<details> and <summary>', '<toggle> and <label>', 'C', 1, 'The browser handles open and close without JavaScript.'),
(1, 'Which element creates a native modal dialog?', '<modal>', '<popup>', '<dialog>', '<window>', 'C', 1, 'dialog.showModal() opens it as a modal.'),
(1, 'When should <meter> be used instead of <progress>?', 'For task completion', 'For a measurement within a known range', 'For video', 'For loading bars', 'B', 1, 'meter shows a gauge such as disk usage; progress shows task progress.'),
(1, 'Which element offers autocomplete suggestions for an input?', '<options>', '<autocomplete>', '<suggest>', '<datalist>', 'D', 1, 'Link input list="id" to a <datalist>.'),
(1, 'Which entity displays the less-than symbol (<)?', '&lt;', '&gt;', '&amp;', '&less;', 'A', 1, 'Entities prevent the browser from treating the character as markup.'),
(1, 'What does &nbsp; produce?', 'An ampersand', 'A tab', 'A non-breaking space', 'A new line', 'C', 1, 'It keeps words together and adds visible space.'),
(1, 'How do you write an HTML comment?', '<!-- comment -->', '// comment', '/* comment */', '# comment', 'A', 1, 'HTML comments are not displayed in the page.'),
(1, 'Which link opens the default email app?', '<a href="mail=me@example.com">', '<a href="mailto:me@example.com">', '<a href="email:me@example.com">', '<a href="send:me@example.com">', 'B', 1, 'The mailto: scheme starts a new email.'),
(1, 'Which link starts a phone call on mobile?', '<a href="call:+911234567890">', '<a href="dial:+911234567890">', '<a href="phone=+911234567890">', '<a href="tel:+911234567890">', 'D', 1, 'The tel: scheme is supported on phones.'),
(1, 'What does <a href="#contact"> do?', 'Jumps to the element with id="contact"', 'Reloads the page', 'Opens a new page named contact', 'Downloads a file', 'A', 1, 'A fragment link scrolls to the matching id.'),
(1, 'Which attribute makes a link download a file instead of navigating?', 'save', 'download', 'get', 'attachment', 'B', 1, '<a href="file.pdf" download> triggers a download.'),
(1, 'What is the correct basic structure of an HTML document?', 'head containing html and body', 'html containing only body', 'body containing head then html', 'html containing head then body', 'D', 1, 'The head holds metadata, the body holds content.'),
(1, 'What is the default behaviour when you omit a closing </p> tag?', 'The paragraph never ends', 'The page crashes', 'The browser usually closes it automatically', 'An error is shown', 'C', 1, 'Browsers fix some invalid markup, but valid closing tags are best practice.'),
(1, 'Are HTML tag names case-sensitive?', 'No', 'Only for attributes', 'Only in HTML5', 'Yes', 'A', 1, 'HTML tags are case-insensitive, though lowercase is the convention.'),
(1, 'Which HTML element would you use for the website logo link in the header?', '<brand>', '<a> wrapping an <img>', '<icon>', '<logo>', 'B', 1, 'There is no logo element; use a link around an image.');
INSERT INTO questions (exam_id, question, option_a, option_b, option_c, option_d, correct_option, marks, explanation) VALUES
(2, 'What does CSS stand for?', 'Cascading Style Sheets', 'Creative Style Syntax', 'Computer Style Sheets', 'Colorful Style Scripts', 'A', 1, 'CSS describes how HTML elements look.'),
(2, 'Which is the correct CSS rule syntax?', '<p> color: red; </p>', 'p : color = red;', 'p ( color: red )', 'p { color: red; }', 'D', 1, 'A rule has a selector and a declaration block of property: value pairs.'),
(2, 'What are the three ways to add CSS to a page?', 'Class, id and tag', 'Local, global and remote', 'Inline, internal and external', 'Head, body and footer', 'C', 1, 'Inline uses the style attribute, internal uses <style>, external uses a linked file.'),
(2, 'Which approach is best for a multi-page website?', 'Styles in every <p> tag', 'An external stylesheet', 'Inline styles', '<font> tags', 'B', 1, 'One file is cached and reused across pages.'),
(2, 'How do you write a CSS comment?', '// comment', '<!-- comment -->', '# comment', '/* comment */', 'D', 1, 'CSS only supports the /* */ comment style.'),
(2, 'Which selector targets elements with class="box"?', '#box', '.box', '*box', 'box', 'B', 1, 'A dot selects by class.'),
(2, 'Which selector targets the element with id="header"?', '#header', 'header', '.header', '*header', 'A', 1, 'A hash selects by id.'),
(2, 'What does the universal selector * do?', 'Selects all classes', 'Selects only the body', 'Selects all elements', 'Selects nothing', 'C', 1, '* matches every element on the page.'),
(2, 'What does h1, h2, p { margin: 0; } do?', 'Applies the rule to h1, h2 and p', 'Causes a syntax error', 'Selects only the last element', 'Selects p inside h2 inside h1', 'A', 1, 'A comma separates a group of selectors.'),
(2, 'What does the selector div p select?', 'All div elements inside p', 'Only p elements that are direct children of div', 'All p elements inside a div', 'A div followed by a p', 'C', 1, 'The space is the descendant combinator.'),
(2, 'What does the selector div > p select?', 'p elements immediately after a div', 'div elements inside p', 'All p inside div at any depth', 'p elements that are direct children of div', 'D', 1, '> is the child combinator.'),
(2, 'What does h1 + p select?', 'A p inside an h1', 'The p immediately after an h1', 'Both h1 and p', 'All p after an h1', 'B', 1, '+ is the adjacent sibling combinator.'),
(2, 'What does h1 ~ p select?', 'p elements before h1', 'Only the first p after h1', 'All p siblings that come after an h1', 'p elements inside h1', 'C', 1, '~ is the general sibling combinator.'),
(2, 'Which selector matches links that open in a new tab?', 'a[target="_blank"]', 'a:target', 'a#_blank', 'a.target', 'A', 1, 'Attribute selectors use square brackets.'),
(2, 'Which pseudo-class styles an element when the mouse is over it?', ':mouse', ':hover', ':over', ':active', 'B', 1, ':hover applies on pointer hover.'),
(2, 'Which pseudo-class styles an element while it is being clicked?', ':click', ':hover', ':press', ':active', 'D', 1, ':active applies during the press.'),
(2, 'Which selector styles even-numbered list items?', 'li:nth(2)', 'li:nth-child(even)', 'li.even()', 'li:even', 'B', 1, ':nth-child(even) or (2n) selects even positions.'),
(2, 'What does p:not(.intro) select?', 'Every p without the class intro', 'Only p with class intro', 'The first p', 'Every element except p', 'A', 1, ':not() excludes matching elements.'),
(2, 'What does :first-child select?', 'The first class in a stylesheet', 'The first paragraph only', 'An element that is the first child of its parent', 'The first element on the page', 'C', 1, 'It matches by position among siblings.'),
(2, 'What does :checked match?', 'Valid form fields', 'Selected text', 'Submitted forms', 'Checked checkboxes and radio buttons', 'D', 1, 'It matches inputs in the checked state.'),
(2, 'What does :focus-visible do?', 'Hides the focus ring', 'Focuses an element on load', 'Styles hovered elements', 'Styles focus only when the browser shows a focus indicator', 'D', 1, 'It is typically used for keyboard focus outlines.'),
(2, 'What is the difference between a pseudo-class and a pseudo-element?', 'A pseudo-element selects a state, a pseudo-class a part', 'They are the same', 'A pseudo-class selects a state, a pseudo-element selects a part of an element', 'Pseudo-classes only work on links', 'C', 1, ':hover is a state; ::before creates a part.'),
(2, 'Which property is required for ::before or ::after to appear?', 'content', 'display', 'visibility', 'position', 'A', 1, 'Without content, generated boxes are not rendered.'),
(2, 'Which pseudo-element styles the first letter of a block?', '::initial', '::first-letter', ':first-char', '::letter', 'B', 1, 'It is used for drop caps.'),
(2, 'Which pseudo-element styles the hint text of an input?', '::input-text', ':hint', '::placeholder', ':placeholder-shown-text', 'C', 1, '::placeholder targets the placeholder text.'),
(2, 'What is the order of specificity from highest to lowest?', 'Inline, id, class, element', 'Element, class, id, inline', 'Id, inline, element, class', 'Class, id, inline, element', 'A', 1, 'Inline styles beat ids, which beat classes and attributes, which beat elements.'),
(2, 'Which selector wins: #nav a or .menu .item a?', '.menu .item a', '#nav a', 'Both are equal', 'The one declared first', 'B', 1, '#nav a is (1,0,1) and beats (0,2,1).'),
(2, 'When two rules have equal specificity, which one applies?', 'Neither', 'The shorter one', 'The one declared first', 'The one declared last', 'D', 1, 'Later rules override earlier ones in the cascade.'),
(2, 'What does !important do?', 'Disables the rule', 'Marks a comment', 'Makes a rule load first', 'Overrides normal specificity for that declaration', 'D', 1, 'Overusing it makes CSS hard to maintain.'),
(2, 'Which property is inherited by default?', 'margin', 'padding', 'color', 'border', 'C', 1, 'Text-related properties like color and font-family inherit; box properties do not.'),
(2, 'Which property is NOT inherited by default?', 'border', 'font-family', 'color', 'line-height', 'A', 1, 'Borders belong to the element itself.'),
(2, 'What does the keyword inherit do?', 'Removes the declaration', 'Takes the value from the parent element', 'Copies from the previous sibling', 'Resets to the default', 'B', 1, 'It forces inheritance for any property.'),
(2, 'What does the keyword initial do?', 'Resets a property to its default specification value', 'Inherits from parent', 'Applies only the first time', 'Hides the element', 'A', 1, 'initial restores the CSS default.'),
(2, 'In the CSS box model, which layers go from the inside out?', 'Margin, border, padding, content', 'Content, padding, border, margin', 'Padding, content, margin, border', 'Content, border, padding, margin', 'B', 1, 'Padding surrounds content, then border, then margin.'),
(2, 'With content-box, what is the total width of: width 200px, padding 20px, border 5px?', '200px', '245px', '225px', '250px', 'D', 1, '200 + 2*20 + 2*5 = 250px.'),
(2, 'With box-sizing: border-box, what is the total width of: width 200px, padding 20px, border 5px?', '225px', '240px', '200px', '250px', 'C', 1, 'Padding and border are included in the stated width.'),
(2, 'Which snippet is a common global reset for box sizing?', '*, *::before, *::after { box-sizing: border-box; }', 'body { box: border; }', '* { box-model: simple; }', 'html { padding: 0; }', 'A', 1, 'It makes sizing predictable everywhere.'),
(2, 'What is margin collapsing?', 'Margins disappear on mobile', 'Margins are added together', 'Adjacent vertical margins combine into the larger one', 'Margins turn into padding', 'C', 1, 'Between block siblings, only the larger margin is kept.'),
(2, 'How do you horizontally centre a block element with a set width?', 'text-align: center;', 'margin: 0 auto;', 'float: center;', 'align: center;', 'B', 1, 'Auto left and right margins split the free space.'),
(2, 'In margin: 10px 20px 30px 40px, which order is used?', 'Top, bottom, left, right', 'Left, top, right, bottom', 'Bottom, left, top, right', 'Top, right, bottom, left', 'D', 1, 'Think clockwise starting at the top.');
INSERT INTO questions (exam_id, question, option_a, option_b, option_c, option_d, correct_option, marks, explanation) VALUES
(2, 'In padding: 5px 10px, what do the values mean?', '5px top, 10px everything else', '5px all sides', '5px left and right, 10px top and bottom', '5px top and bottom, 10px left and right', 'D', 1, 'Two values mean vertical then horizontal.'),
(2, 'What is the difference between display: none and visibility: hidden?', 'none removes the element from layout, hidden keeps its space', 'none only hides text', 'They are identical', 'hidden removes the space, none keeps it', 'A', 1, 'visibility: hidden keeps the box but makes it invisible.'),
(2, 'Which display value lets elements sit inline but accept width and height?', 'inline', 'contents', 'inline-block', 'block', 'C', 1, 'inline-block combines both behaviours.'),
(2, 'Do inline elements respect width and height?', 'Only width', 'No', 'Yes', 'Only height', 'B', 1, 'Inline boxes size to their content.'),
(2, 'What is the default value of position?', 'relative', 'fixed', 'absolute', 'static', 'D', 1, 'Static elements follow normal flow and ignore top, left, etc.'),
(2, 'position: relative offsets an element relative to what?', 'Its own normal position', 'The viewport', 'The body', 'The nearest positioned ancestor', 'A', 1, 'The original space it occupied stays reserved.'),
(2, 'position: absolute is positioned relative to what?', 'The previous sibling', 'Its own normal position', 'The nearest positioned ancestor', 'The viewport', 'C', 1, 'If none exists, it uses the initial containing block.'),
(2, 'position: fixed is positioned relative to what?', 'The previous element', 'The viewport', 'The document body only', 'The parent', 'B', 1, 'Fixed elements stay in place while scrolling.'),
(2, 'What does position: sticky do?', 'Acts relative until a scroll threshold, then sticks', 'Makes an element draggable', 'Pins to the bottom of the document', 'Always stays at the top', 'A', 1, 'It needs a threshold such as top: 0.'),
(2, 'On which elements does z-index work?', 'Only absolute elements', 'Every static element', 'Only fixed elements', 'Positioned elements and flex or grid items', 'D', 1, 'Static non-flex elements ignore z-index.'),
(2, 'What does clear: both do?', 'Removes all margins', 'Moves an element below any floated elements', 'Clears the background', 'Empties the element', 'B', 1, 'It stops an element wrapping around floats.'),
(2, 'What does overflow: hidden do?', 'Adds scrollbars', 'Shrinks the content', 'Clips content that overflows the box', 'Hides the whole element', 'C', 1, 'Overflowing content is cut off.'),
(2, 'Which overflow value shows scrollbars only when needed?', 'visible', 'auto', 'scroll', 'hidden', 'B', 1, 'auto adds scrollbars if content overflows.'),
(2, 'If the root font-size is 16px, what is 1.5rem?', '16px', '15px', '32px', '24px', 'D', 1, '1.5 * 16 = 24px.'),
(2, 'If a parent has font-size 20px, what is font-size: 2em on the child?', '20px', '22px', '40px', '2px', 'C', 1, 'em is relative to the parent font size for font-size.'),
(2, 'What is the difference between em and rem?', 'em depends on the parent, rem on the root element', 'em is absolute', 'rem depends on the parent, em on the root', 'They are the same', 'A', 1, 'rem keeps sizes consistent across the page.'),
(2, 'What does 1vh represent?', '1 pixel of height', '1% of the parent height', '1% of the viewport height', '1 inch of height', 'C', 1, 'vh stands for viewport height.'),
(2, 'If font-size is 20px, what is padding: 1em on that element?', '20px', '16px', '1px', '10px', 'A', 1, 'em for non-font properties uses the element''s own font size.'),
(2, 'What does line-height: 1.5 mean?', '1.5 pixels', '150px', '1.5em of the parent only', '1.5 times the element''s font size', 'D', 1, 'A unitless value scales with the font size.'),
(2, 'Which numeric font-weight is the standard "bold"?', '100', '700', '400', '300', 'B', 1, '400 is normal and 700 is bold.'),
(2, 'Which property transforms text to capitals?', 'font-variant: upper', 'text-decoration: caps', 'font-style: uppercase', 'text-transform: uppercase', 'D', 1, 'text-transform changes letter case without editing the HTML.'),
(2, 'Which property removes the underline from links?', 'text-decoration: none', 'underline: none', 'text-style: none', 'font-decoration: none', 'A', 1, 'text-decoration controls underline, overline and line-through.'),
(2, 'Which declaration provides font fallbacks?', 'typeface: Poppins, Arial;', 'font-fallback: Arial;', 'font-family: "Poppins", Arial, sans-serif;', 'font: Poppins only;', 'C', 1, 'The browser uses the next font if the first is unavailable.'),
(2, 'Which at-rule loads a custom font file?', '@import-font', '@font-face', '@typeface', '@custom-font', 'B', 1, '@font-face defines a font family and its source.'),
(2, 'Which colour value is white?', '#fff', '#0f0', '#f00', '#000', 'A', 1, '#fff is shorthand for #ffffff.'),
(2, 'What does the A in rgba() control?', 'Brightness', 'Opacity', 'Saturation', 'Angle', 'B', 1, 'Alpha is transparency from 0 to 1.'),
(2, 'What does background-size: cover do?', 'Fits the whole image with gaps', 'Stretches it ignoring ratio', 'Scales the image to fill the box, possibly cropping', 'Repeats the image', 'C', 1, 'cover fills; contain fits fully inside.'),
(2, 'What does background-size: contain do?', 'Removes the image', 'Fills the box and crops', 'Repeats the image', 'Scales the image to fit entirely inside the box', 'D', 1, 'contain keeps the whole image visible.'),
(2, 'Which function creates a gradient background?', 'linear-gradient()', 'blend()', 'fade()', 'gradient-color()', 'A', 1, 'background: linear-gradient(to right, red, blue).'),
(2, 'What does border-radius: 50% produce on a square element?', 'A square with thick borders', 'A triangle', 'A hexagon', 'A circle', 'D', 1, '50% rounds corners to half the side.'),
(2, 'In box-shadow: 2px 4px 6px red, what is 4px?', 'Horizontal offset', 'Blur radius', 'Vertical offset', 'Spread radius', 'C', 1, 'The order is x offset, y offset, blur, spread, colour.'),
(2, 'How do you make an element a flex container?', 'position: flex', 'display: flex', 'flex: container', 'layout: flex', 'B', 1, 'display: flex enables flexbox for the children.'),
(2, 'What is the default value of flex-direction?', 'column-reverse', 'row-reverse', 'column', 'row', 'D', 1, 'Flex items lay out horizontally by default.'),
(2, 'Which property aligns flex items along the main axis?', 'align-items', 'justify-content', 'align-content', 'place-items', 'B', 1, 'justify-content works on the main axis.'),
(2, 'Which property aligns flex items along the cross axis?', 'align-items', 'justify-content', 'flex-flow', 'align-main', 'A', 1, 'align-items works on the cross axis.'),
(2, 'With flex-direction: column, which axis does justify-content control?', 'Both', 'Neither', 'Vertical', 'Horizontal', 'C', 1, 'The main axis follows the flex direction.'),
(2, 'Which two declarations centre a child both ways in a flex container?', 'justify-content: center; align-items: center;', 'margin: center;', 'text-align: center; vertical-align: middle;', 'flex: center;', 'A', 1, 'They centre on the main and cross axes.'),
(2, 'What is the default value of flex-wrap?', 'wrap-reverse', 'auto', 'wrap', 'nowrap', 'D', 1, 'Items squeeze onto one line by default.'),
(2, 'What does flex: 1 do?', 'Orders the item first', 'Lets the item grow to share available space', 'Sets the item width to 1px', 'Disables shrinking', 'B', 1, 'It is shorthand for flex-grow 1, flex-shrink 1, flex-basis 0.'),
(2, 'What does the gap property do?', 'Adds padding inside items', 'Adds margin outside the container', 'Adds space between flex or grid items', 'Adds a border', 'C', 1, 'gap works in flexbox and grid.');
INSERT INTO questions (exam_id, question, option_a, option_b, option_c, option_d, correct_option, marks, explanation) VALUES
(2, 'What does margin-left: auto do to a flex item?', 'Pushes it to the far right', 'Hides it', 'Centres it', 'Removes its margin', 'A', 1, 'Auto margins absorb free space.'),
(2, 'Which property lets one flex item override alignment?', 'justify-self', 'align-self', 'align-content', 'flex-align', 'B', 1, 'align-self sets alignment for a single item.'),
(2, 'What does the order property do on flex items?', 'Counts items', 'Sets the z-index', 'Changes visual order without changing the HTML', 'Sorts the DOM', 'C', 1, 'Lower order values appear first.'),
(2, 'What is the main difference between Flexbox and Grid?', 'They are the same', 'Flexbox is two-dimensional, Grid is one-dimensional', 'Grid only works on tables', 'Flexbox is one-dimensional, Grid is two-dimensional', 'D', 1, 'Flex handles a row or column; grid handles rows and columns together.'),
(2, 'What does grid-template-columns: repeat(3, 1fr) create?', 'Three rows', 'Three fixed 1px columns', 'Three equal-width columns', 'One column 3px wide', 'C', 1, '1fr is one share of the free space.'),
(2, 'What is the fr unit?', 'A fixed frame size', 'A frequency unit', 'A font ratio', 'A fraction of the available space', 'D', 1, 'fr distributes remaining space in a grid.'),
(2, 'What does grid-column: 1 / 3 mean?', 'From line 1 to line 3, spanning two columns', 'A ratio of 1 to 3', 'Three columns wide', 'Columns 1 and 3 only', 'A', 1, 'Grid lines are numbered; it ends before line 3.'),
(2, 'Which declaration builds a responsive grid without media queries?', 'grid: responsive;', 'grid-template-columns: repeat(auto-fit, minmax(200px, 1fr));', 'grid-template-columns: auto;', 'columns: fluid;', 'B', 1, 'auto-fit with minmax adapts column count to width.'),
(2, 'What does place-items: center do in a grid container?', 'Centres the container', 'Centres text only', 'Centres items horizontally and vertically', 'Places items last', 'C', 1, 'It is shorthand for align-items and justify-items.'),
(2, 'What is the difference between auto-fit and auto-fill?', 'auto-fit collapses empty tracks, auto-fill keeps them', 'They are identical', 'auto-fit only works on rows', 'auto-fill collapses empty tracks', 'A', 1, 'auto-fit stretches items to use the empty space.'),
(2, 'Which media query applies styles on screens 768px wide or smaller?', '@media (min-width: 768px)', '@media (width > small)', '@media screen = 768px', '@media (max-width: 768px)', 'D', 1, 'max-width means up to and including that width.'),
(2, 'What does a mobile-first approach use?', 'max-width media queries only', 'min-width media queries', 'No media queries', 'Fixed pixel layouts', 'B', 1, 'Base styles target small screens, then grow with min-width.'),
(2, 'Why is the viewport meta tag needed for responsive design?', 'Mobile browsers otherwise render at a desktop width', 'It loads media queries', 'It enables Flexbox', 'It compresses images', 'A', 1, 'width=device-width makes CSS pixels match the device.'),
(2, 'How do you make an image never overflow its container?', 'display: inline;', 'max-width: 100%; height: auto;', 'overflow: scroll;', 'width: 100vw;', 'B', 1, 'It scales the image down but never up beyond its size.'),
(2, 'What does clamp(1rem, 2.5vw, 2rem) do?', 'Adds the three values', 'Picks the smallest unit', 'Always returns 2.5vw', 'Keeps a fluid value between a minimum and maximum', 'D', 1, 'The result never goes below 1rem or above 2rem.'),
(2, 'Which declaration is valid?', 'width: calc(100%-50px);', 'width: calc[100% - 50px];', 'width: calc(100% - 50px);', 'width: calc(100% - 50 px);', 'C', 1, 'Operators + and - need spaces around them in calc().'),
(2, 'How do you define a custom property (CSS variable)?', '$main-color: #7c5cff;', '--main-color: #7c5cff;', 'var main-color = #7c5cff;', '@main-color: #7c5cff;', 'B', 1, 'Custom properties start with two dashes.'),
(2, 'How do you use a CSS variable?', 'color: get(--main-color);', 'color: --main-color;', 'color: $main-color;', 'color: var(--main-color);', 'D', 1, 'var() reads the custom property value.'),
(2, 'Where are global CSS variables usually defined?', 'In the body tag attributes', 'In <meta> tags', 'In the :root selector', 'In @import', 'C', 1, ':root matches the html element, so variables are available everywhere.'),
(2, 'Which property sets how the CSS transition behaves over time?', 'transition-timing-function', 'transition-curve', 'transition-style', 'animation-speed', 'A', 1, 'ease, linear and ease-in-out are timing functions.'),
(2, 'Which shorthand is a valid transition?', 'transition = 0.3s;', 'transition: 0.3s all ease-in-out-fast;', 'transition: ease; time: 0.3s;', 'transition: all 0.3s ease;', 'D', 1, 'Format: property duration timing-function delay.'),
(2, 'What defines the steps of a CSS animation?', '@motion', '@animate', '@keyframes', '@steps', 'C', 1, '@keyframes names the animation and its states.'),
(2, 'Which property makes an animation loop forever?', 'animation-loop: true', 'animation-iteration-count: infinite', 'animation-repeat: always', 'animation-forever: on', 'B', 1, 'infinite repeats it without stopping.'),
(2, 'What does animation-fill-mode: forwards do?', 'Keeps the final keyframe styles after the animation ends', 'Delays the animation', 'Plays the animation backwards', 'Skips the first keyframe', 'A', 1, 'Without it, styles revert after the animation.'),
(2, 'What is the difference between a transition and an animation?', 'They are identical', 'A transition needs a state change trigger, an animation can run on its own', 'Animations need JavaScript', 'Transitions allow multiple keyframes', 'B', 1, 'Animations use @keyframes and can loop automatically.'),
(2, 'Which transform moves an element along the x and y axes?', 'move()', 'slide()', 'shift()', 'translate()', 'D', 1, 'transform: translate(20px, 10px).'),
(2, 'Which pair is the classic trick to centre an absolutely positioned element?', 'top: 50%; left: 50%; transform: translate(-50%, -50%);', 'margin: auto; float: center;', 'position: middle;', 'align: center center;', 'A', 1, 'The transform offsets the element by half its own size.'),
(2, 'Which property keeps an image''s aspect ratio while filling a box?', 'img-size: cover', 'image-fit: fill', 'object-fit: cover', 'aspect: keep', 'C', 1, 'object-fit controls how replaced content fits its box.'),
(2, 'What does aspect-ratio: 16 / 9 do?', 'Sets a 16 column grid', 'Keeps the element in a 16:9 proportion', 'Rotates the element', 'Sets width to 16px', 'B', 1, 'It sets a preferred width-to-height ratio.'),
(2, 'Which three properties are needed for text-overflow: ellipsis to work on one line?', 'display: flex and gap', 'word-wrap and hyphens', 'position and z-index', 'overflow: hidden and white-space: nowrap', 'D', 1, 'The text must be clipped and kept from wrapping.'),
(2, 'What does cursor: pointer do?', 'Makes the element clickable', 'Hides the cursor', 'Shows the hand cursor', 'Moves the pointer', 'C', 1, 'It only changes appearance; it does not add click behaviour.'),
(2, 'What does pointer-events: none do?', 'Lets mouse events pass through the element', 'Hides the element', 'Disables the element''s colour', 'Disables keyboard focus', 'A', 1, 'The element cannot be the target of pointer events.'),
(2, 'What does currentColor refer to?', 'A default black', 'The element''s current color value', 'The last used colour', 'The page background', 'B', 1, 'It lets borders or icons follow the text colour.'),
(2, 'What does list-style: none do?', 'Removes bullets or numbers from a list', 'Hides list items', 'Makes the list inline', 'Deletes the list', 'A', 1, 'It is common in navigation menus.'),
(2, 'What does border-collapse: collapse do on a table?', 'Removes cell padding', 'Hides the table borders', 'Collapses empty rows', 'Merges adjacent cell borders into single lines', 'D', 1, 'The default separate model shows double borders.'),
(2, 'How does outline differ from border?', 'Outline cannot be coloured', 'Outline takes up space like border', 'Outline does not take up space in the layout', 'Border does not support styles', 'C', 1, 'Outlines are drawn outside the box without affecting layout.'),
(2, 'What does inset: 0 mean on a positioned element?', 'Padding is 0', 'It adds an inner shadow', 'top, right, bottom and left are all 0', 'The element is hidden', 'C', 1, 'inset is shorthand for the four offset properties.'),
(2, 'Which function adds a blur to what is behind an element?', 'backdrop-filter: blur()', 'blur-behind: 5px', 'background-blur: on', 'filter: behind()', 'A', 1, 'backdrop-filter affects the area behind the element.'),
(2, 'Which media feature supports dark mode?', 'dark-mode', 'prefers-color-scheme', 'night-mode', 'color-theme', 'B', 1, '@media (prefers-color-scheme: dark) targets users who chose dark mode.'),
(2, 'Why use prefers-reduced-motion?', 'To detect slow devices', 'To speed up animations', 'To disable transitions for everyone', 'To respect users who want less animation', 'D', 1, 'It supports accessibility for motion sensitivity.');
INSERT INTO questions (exam_id, question, option_a, option_b, option_c, option_d, correct_option, marks, explanation) VALUES
(2, 'What is BEM naming?', 'Basic Element Markup', 'Block__element--modifier', 'Border Edge Margin', 'Browser Element Model', 'B', 1, 'BEM keeps class names structured, e.g. card__title--large.'),
(2, 'Why is @import often slower than a <link> tag?', 'It blocks images', '@import is not supported', 'The imported file is discovered late, delaying parallel loading', 'It compresses CSS', 'C', 1, 'Links let the browser fetch stylesheets in parallel.'),
(2, 'What is the purpose of a CSS reset or normalize?', 'Speed up JavaScript', 'Encrypt styles', 'Delete all CSS', 'Reduce browser default style differences', 'D', 1, 'It gives a consistent baseline across browsers.'),
(2, 'What does :root select?', 'The html element', 'The first div', 'The body element', 'Elements with id root', 'A', 1, ':root has higher specificity than html and holds variables.'),
(2, 'What does :has() allow you to do?', 'Select an element based on what it contains', 'Select hidden elements', 'Select empty elements', 'Select the parent of the body', 'A', 1, 'It acts as a parent selector, e.g. div:has(img).'),
(2, 'What does resize: none do on a textarea?', 'Disables typing', 'Removes the border', 'Prevents the user from resizing it', 'Makes it fixed in size and hidden', 'C', 1, 'It hides the resize handle.'),
(2, 'What does flex-shrink: 0 do?', 'Makes it grow', 'Prevents the item from shrinking', 'Hides overflow', 'Removes it from layout', 'B', 1, 'The item keeps its size when space is tight.'),
(2, 'What does min-height: 100vh do on a container?', 'Hides overflow', 'Limits the height', 'Makes it exactly 100px', 'Makes it at least as tall as the viewport', 'D', 1, 'It is common for full-screen sections.'),
(2, 'What does scroll-behavior: smooth do?', 'Locks scrolling', 'Animates scrolling to anchors', 'Speeds up scrolling', 'Hides scrollbars', 'B', 1, 'It smooths jumps from in-page links.'),
(2, 'What does white-space: nowrap do?', 'Adds a space', 'Removes spaces', 'Wraps text always', 'Prevents text from wrapping to a new line', 'D', 1, 'Text stays on one line until a <br>.'),
(2, 'What does overflow-wrap: break-word do?', 'Breaks long words to prevent overflow', 'Hyphenates all words', 'Adds ellipsis', 'Hides long words', 'A', 1, 'It lets long strings wrap inside the container.'),
(2, 'What does Sass add to CSS?', 'A new browser engine', 'Server-side rendering', 'Variables, nesting and mixins', 'JavaScript animations', 'C', 1, 'Sass is a preprocessor that compiles to CSS.'),
(2, 'Why is CSS considered render-blocking?', 'The browser waits for CSS before painting', 'It blocks images only', 'It blocks JavaScript', 'It delays the server', 'A', 1, 'This avoids flashes of unstyled content.'),
(2, 'Which of these floats an element to the left so text wraps around it?', 'text-float: left', 'align: left', 'float: left', 'position: left', 'C', 1, 'float moves an element to one side and lets inline content wrap.');
INSERT INTO questions (exam_id, question, option_a, option_b, option_c, option_d, correct_option, marks, explanation) VALUES
(3, 'Which keyword declares a block-scoped variable that can be reassigned?', 'var', 'let', 'const', 'def', 'B', 1, 'let is block-scoped and reassignable; const is block-scoped but cannot be reassigned.'),
(3, 'What scope does a variable declared with var have?', 'Function scope', 'Statement scope', 'Block scope', 'Module scope only', 'A', 1, 'var ignores blocks such as if and for, and is scoped to the enclosing function.'),
(3, 'After const user = { age: 20 }; what does user.age = 21; do?', 'Is silently ignored', 'Throws a TypeError', 'Throws a SyntaxError', 'Works, because const protects the binding not the contents', 'D', 1, 'You cannot reassign user, but you can mutate the object it points to.'),
(3, 'What does console.log(x); var x = 5; print?', 'ReferenceError', '5', 'undefined', 'null', 'C', 1, 'The var declaration is hoisted and initialised with undefined.'),
(3, 'What does console.log(y); let y = 5; do?', 'Throws a ReferenceError', 'Prints null', 'Prints undefined', 'Prints 5', 'A', 1, 'let variables are in the temporal dead zone until their declaration runs.'),
(3, 'What is the temporal dead zone?', 'The delay of setTimeout', 'The time between entering a scope and the let/const declaration being executed', 'A bug in old browsers', 'The time a script takes to load', 'B', 1, 'Accessing the variable in this period throws a ReferenceError.'),
(3, 'What is hoisting?', 'Moving code to the top of the file physically', 'Loading scripts in parallel', 'Declarations are processed before code executes', 'Compressing code', 'C', 1, 'Function declarations and var are registered during the creation phase.'),
(3, 'What does typeof null return?', '"number"', '"null"', '"undefined"', '"object"', 'D', 1, 'This is a long-standing bug kept for backward compatibility.'),
(3, 'What does typeof undefined return?', '"void"', '"null"', '"undefined"', '"object"', 'C', 1, 'undefined is its own primitive type.'),
(3, 'What does typeof [] return?', '"object"', '"number"', '"array"', '"list"', 'A', 1, 'Arrays are objects; use Array.isArray() to detect them.'),
(3, 'What does typeof NaN return?', '"NaN"', '"undefined"', '"object"', '"number"', 'D', 1, 'NaN is a special numeric value.'),
(3, 'What does typeof function(){} return?', '"callable"', '"function"', '"method"', '"object"', 'B', 1, 'Functions are objects with a special typeof result.'),
(3, 'What does typeof typeof 1 return?', '"object"', '"undefined"', '"string"', '"number"', 'C', 1, 'typeof 1 is "number", and typeof "number" is "string".'),
(3, 'What does typeof an undeclared variable return, for example typeof notDefined?', 'It throws a ReferenceError', '"object"', '"null"', '"undefined"', 'D', 1, 'typeof is safe on undeclared identifiers.'),
(3, 'Which of these is a non-primitive (reference) type?', 'Boolean', 'Object', 'String', 'Symbol', 'B', 1, 'Objects, arrays and functions are reference types.'),
(3, 'Which of these is NOT a primitive type in JavaScript?', 'Array', 'Boolean', 'BigInt', 'Symbol', 'A', 1, 'Arrays are objects.'),
(3, 'What is the result of "5" + 2?', 'NaN', '7', '"52"', '52 as a number', 'C', 1, 'With a string operand, + concatenates.'),
(3, 'What is the result of "5" - 2?', '"52"', '3', '"3"', 'NaN', 'B', 1, 'The - operator converts both operands to numbers.'),
(3, 'What is the result of "5" * "2"?', '"10"', 'NaN', '"52"', '10', 'D', 1, 'The * operator converts strings to numbers.'),
(3, 'What is the result of true + 1?', '2', '1', '"true1"', 'NaN', 'A', 1, 'true converts to 1 in arithmetic.'),
(3, 'What is the result of null + 1?', 'NaN', 'null', '"null1"', '1', 'D', 1, 'null converts to 0 in arithmetic.'),
(3, 'What is the result of undefined + 1?', 'NaN', 'undefined', '"undefined1"', '1', 'A', 1, 'undefined converts to NaN in arithmetic.'),
(3, 'What is the result of [] + []?', 'An empty array', 'An empty string', 'NaN', '0', 'B', 1, 'Both arrays convert to empty strings, which are concatenated.'),
(3, 'What does "b" + "a" + +"a" + "a" evaluate to?', '"ba0a"', 'NaN', '"baNaNa"', '"baaa"', 'C', 1, 'The unary +"a" becomes NaN, which is then concatenated as text.'),
(3, 'What does 3 > 2 > 1 evaluate to?', 'undefined', 'It throws an error', 'true', 'false', 'D', 1, '3 > 2 is true, then true > 1 becomes 1 > 1, which is false.'),
(3, 'What does 0.1 + 0.2 === 0.3 evaluate to?', 'false', 'NaN', 'true', 'undefined', 'A', 1, 'Binary floating point cannot represent 0.1 and 0.2 exactly.'),
(3, 'What does NaN === NaN evaluate to?', 'true', 'undefined', 'false', 'It throws an error', 'C', 1, 'NaN is the only value not equal to itself.'),
(3, 'Which is the reliable way to check for NaN?', 'typeof value === "NaN"', 'Number.isNaN(value)', 'value === NaN', 'value == NaN', 'B', 1, 'Number.isNaN does not coerce and works correctly.'),
(3, 'What does Number.isNaN("abc") return?', 'It throws', 'true', 'undefined', 'false', 'D', 1, '"abc" is not the value NaN, even though it is not a number; the global isNaN would return true.'),
(3, 'What is the main difference between == and ===?', '=== only works on numbers', 'There is no difference', '=== compares value and type without coercion', '== compares value and type', 'C', 1, '== performs type coercion before comparing.'),
(3, 'What does null == undefined evaluate to?', 'NaN', 'true', 'false', 'It throws', 'B', 1, 'They are loosely equal but not strictly equal.'),
(3, 'What does null === undefined evaluate to?', 'false', 'It throws', 'true', 'NaN', 'A', 1, 'They are different types.'),
(3, 'What does {} === {} evaluate to?', 'true', 'It throws', 'undefined', 'false', 'D', 1, 'Objects are compared by reference, and these are two different objects.'),
(3, 'Which of these values is falsy?', '[]', '"0"', '0', '{}', 'C', 1, 'The numeric 0 is falsy; a non-empty string, an array and an object are truthy.'),
(3, 'What does Boolean([]) return?', 'true', 'null', 'undefined', 'false', 'A', 1, 'Empty arrays and objects are truthy.'),
(3, 'What does !!"false" evaluate to?', 'undefined', 'true', '"false"', 'false', 'B', 1, 'Any non-empty string is truthy.'),
(3, 'Which list contains only falsy values?', '0, "", null, undefined, NaN', '-1, "", null', 'false, [], 0', '0, "0", [], {}', 'A', 1, 'The falsy values are false, 0, -0, 0n, "", null, undefined and NaN.'),
(3, 'What does 0 || "default" return?', 'true', '0', 'false', '"default"', 'D', 1, '|| returns the first truthy operand, and 0 is falsy.'),
(3, 'What does 0 ?? "default" return?', 'undefined', '"default"', '0', 'null', 'C', 1, '?? only falls back for null or undefined.'),
(3, 'What does user?.address?.city return if user.address is undefined?', 'An empty string', 'undefined', 'null', 'It throws a TypeError', 'B', 1, 'Optional chaining short-circuits safely.');
INSERT INTO questions (exam_id, question, option_a, option_b, option_c, option_d, correct_option, marks, explanation) VALUES
(3, 'What does 2 ** 3 evaluate to?', '5', '6', '8', '9', 'C', 1, '** is the exponentiation operator.'),
(3, 'What does 10 % 3 evaluate to?', '1', '3', '3.33', '0', 'A', 1, '% returns the remainder.'),
(3, 'After let a = 5; let b = a++; what are a and b?', 'Both are 6', 'Both are 5', 'a is 5 and b is 6', 'a is 6 and b is 5', 'D', 1, 'Post-increment returns the old value, then increments.'),
(3, 'Can you call a function declaration before it appears in the code?', 'Only inside a module', 'Yes, because it is hoisted', 'No, it throws a ReferenceError', 'Only with async', 'B', 1, 'Function declarations are hoisted with their bodies.'),
(3, 'What happens if you call a function expression stored in a const before its line runs?', 'ReferenceError', 'It returns null', 'It works normally', 'It returns undefined', 'A', 1, 'The const is in the temporal dead zone.'),
(3, 'What is the output of const sq = x => x * x; sq(4)?', '8', '16', '4', 'undefined', 'B', 1, 'An arrow function with an expression body returns it implicitly.'),
(3, 'What is a key difference between arrow functions and regular functions?', 'Arrow functions have their own arguments object', 'Arrow functions can be used as constructors', 'Arrow functions do not have their own this', 'Arrow functions are always faster', 'C', 1, 'They capture this from the surrounding scope.'),
(3, 'Can you use new with an arrow function?', 'Only with async', 'Yes, always', 'Only in strict mode', 'No, it throws a TypeError', 'D', 1, 'Arrow functions have no prototype and are not constructors.'),
(3, 'What does function greet(name = "Guest") demonstrate?', 'A closure', 'A generator', 'A default parameter', 'A rest parameter', 'C', 1, 'The default is used when the argument is undefined.'),
(3, 'In function f(...args), what is args?', 'A real array of the remaining arguments', 'A number', 'A string', 'An array-like object only', 'A', 1, 'Rest parameters collect extra arguments into an array.'),
(3, 'What does [...a, ...b] do?', 'Throws an error', 'Creates a new array containing the items of a then b', 'Adds b as one nested item', 'Modifies a in place', 'B', 1, 'Spread expands iterables into individual elements.'),
(3, 'What is a closure?', 'A private class', 'A function with no parameters', 'A way to close the browser window', 'A function that remembers variables from its outer scope', 'D', 1, 'Closures keep access to the lexical environment where they were created.'),
(3, 'What does the following print: function counter(){ let c = 0; return () => ++c; } const n = counter(); n(); console.log(n());', '2', '0', 'undefined', '1', 'A', 1, 'The inner function keeps its own persistent c.'),
(3, 'What does for (var i = 0; i < 3; i++) setTimeout(() => console.log(i), 0); print?', '1 2 3', '3 3 3', '0 0 0', '0 1 2', 'B', 1, 'var is shared across iterations, so the callbacks see the final value.'),
(3, 'What does for (let i = 0; i < 3; i++) setTimeout(() => console.log(i), 0); print?', '3 3 3', '1 2 3', 'undefined x3', '0 1 2', 'D', 1, 'let creates a new binding for each iteration.'),
(3, 'What is an IIFE?', 'A function that runs on a timer', 'An inherited function', 'A function that runs immediately after it is defined', 'An imported function', 'C', 1, 'It is written as (function () { ... })();'),
(3, 'What is a callback function?', 'A function that returns a promise', 'A function passed as an argument to be called later', 'A function that calls itself', 'A function with no name', 'B', 1, 'Callbacks are used for events, timers and array methods.'),
(3, 'What is a higher-order function?', 'A function that uses recursion', 'A function declared at the top of the file', 'A function that takes or returns another function', 'A function with many parameters', 'C', 1, 'map, filter and reduce are higher-order functions.'),
(3, 'What is a pure function?', 'Same input always gives the same output, with no side effects', 'A function that uses global variables', 'A function that returns nothing', 'A function with no parameters', 'A', 1, 'Pure functions are predictable and easy to test.'),
(3, 'What does every recursive function need?', 'A callback', 'A global variable', 'An async keyword', 'A base case', 'D', 1, 'Without a base case it recurses forever.'),
(3, 'What error is thrown by infinite recursion?', 'SyntaxError', 'TypeError', 'ReferenceError', 'RangeError: Maximum call stack size exceeded', 'D', 1, 'The call stack overflows.'),
(3, 'What does this refer to when you call obj.method()?', 'The method itself', 'window', 'obj', 'undefined', 'C', 1, 'In a method call, this is the object before the dot.'),
(3, 'What is this inside a standalone regular function in non-strict mode in a browser?', 'The window object', 'undefined', 'null', 'The function itself', 'A', 1, 'In strict mode it would be undefined.'),
(3, 'Which method creates a new function with this permanently set?', 'attach()', 'bind()', 'apply()', 'call()', 'B', 1, 'bind returns a new bound function; call and apply invoke immediately.'),
(3, 'What is the difference between call and apply?', 'call is async', 'call takes arguments separately, apply takes an array', 'call takes an array, apply takes separate arguments', 'There is no difference', 'B', 1, 'fn.call(obj, a, b) versus fn.apply(obj, [a, b]).'),
(3, 'What does arr.push(4) return?', 'The new length of the array', 'The added element', 'undefined', 'The array', 'A', 1, 'push returns the new length.'),
(3, 'What does arr.pop() return?', 'undefined always', 'The new length', 'The array', 'The removed last element', 'D', 1, 'pop removes and returns the last item.'),
(3, 'Which method removes the first element of an array?', 'pop()', 'unshift()', 'shift()', 'splice(1)', 'C', 1, 'shift removes the first item; unshift adds to the start.'),
(3, 'What does map() return?', 'A filtered array', 'A new array of the same length', 'A single value', 'undefined', 'B', 1, 'Each element is transformed by the callback.'),
(3, 'What does filter() return?', 'The first matching element', 'A boolean', 'A new array with elements that pass the test', 'The same array modified', 'C', 1, 'Only elements for which the callback returns truthy are kept.'),
(3, 'What is the result of [1, 2, 3, 4].reduce((a, b) => a + b, 0)?', '24', '4', '[1, 2, 3, 4]', '10', 'D', 1, 'reduce accumulates the sum starting from 0.'),
(3, 'What does forEach() return?', 'undefined', 'The original array', 'The last callback result', 'A new array', 'A', 1, 'forEach is for side effects; use map to transform.'),
(3, 'What does find() return when nothing matches?', 'null', '-1', 'undefined', 'false', 'C', 1, 'findIndex returns -1; find returns undefined.'),
(3, 'What does [1, 2, 3].includes(2) return?', '2', 'true', 'false', '1', 'B', 1, 'includes returns a boolean.'),
(3, 'What do some() and every() return?', 'A boolean', 'A number', 'An array', 'The first element', 'A', 1, 'some needs at least one match; every needs all to match.'),
(3, 'What is the key difference between slice and splice?', 'Neither changes the original', 'slice changes the original array, splice does not', 'Both change the original', 'splice changes the original array, slice does not', 'D', 1, 'slice returns a copy of a portion.'),
(3, 'What does [1, 2, 3, 4].slice(1, 3) return?', '[1, 2]', '[2, 3]', '[1, 2, 3]', '[2, 3, 4]', 'B', 1, 'The end index is not included.'),
(3, 'What does [10, 9, 1].sort() return?', '[9, 10, 1]', '[10, 9, 1]', '[1, 9, 10]', '[1, 10, 9]', 'D', 1, 'The default sort compares elements as strings.'),
(3, 'How do you sort numbers in ascending order?', 'arr.sort((a, b) => b - a)', 'arr.sort()', 'arr.sort((a, b) => a - b)', 'arr.order()', 'C', 1, 'A compare function is needed for numeric sorting.'),
(3, 'How do you remove duplicates from an array?', '[...new Set(arr)]', 'arr.unique()', 'arr.distinct()', 'arr.filter(Boolean)', 'A', 1, 'A Set only stores unique values.');
INSERT INTO questions (exam_id, question, option_a, option_b, option_c, option_d, correct_option, marks, explanation) VALUES
(3, 'What does [1, [2, [3]]].flat() return?', '[1, 2, [3]]', '[1, [2, [3]]]', '[1, 2, 3]', '[[1], [2], [3]]', 'A', 1, 'flat() goes one level deep by default.'),
(3, 'What does Array.isArray([]) return?', 'undefined', '"array"', 'false', 'true', 'D', 1, 'It is the reliable way to detect arrays.'),
(3, 'What does ["a", "b"].join("-") return?', '"a,b"', '"a-b"', '"ab"', '["a-b"]', 'B', 1, 'join builds a string with the given separator.'),
(3, 'What does indexOf return when the item is not found?', 'undefined', 'null', '-1', '0', 'C', 1, '-1 means not found.'),
(3, 'What does Array.from("abc") return?', '["abc"]', '3', '["a", "b", "c"]', '"abc"', 'C', 1, 'Array.from converts iterables and array-likes into arrays.'),
(3, 'What does new Set([1, 1, 2, 3, 3]).size equal?', '5', '3', '2', '1', 'B', 1, 'The set keeps 1, 2 and 3.'),
(3, 'What is a key advantage of Map over a plain object?', 'Keys can be of any type', 'Maps cannot be iterated', 'Maps are JSON-serialisable by default', 'Maps are always faster', 'A', 1, 'Object keys are strings or symbols only.'),
(3, 'What does Object.keys(obj) return?', 'A string', 'An array of values', 'A Set of keys', 'An array of the object''s own enumerable keys', 'D', 1, 'Object.values gives the values and Object.entries gives pairs.'),
(3, 'What does Object.entries({a: 1}) return?', '[["a", 1]]', '["a", 1]', '[{a: 1}]', '{a: 1}', 'A', 1, 'It returns an array of [key, value] pairs.'),
(3, 'What does Object.freeze(obj) do?', 'Hides the object', 'Deep copies the object', 'Prevents adding, removing or changing properties (shallowly)', 'Makes the object a constant variable', 'C', 1, 'Nested objects can still be changed.'),
(3, 'Which creates a shallow copy of an object?', 'obj.clone()', '{ ...obj }', 'const copy = obj', 'copy(obj)', 'B', 1, 'Spread copies top-level properties; nested objects are shared.'),
(3, 'Which creates a deep copy of an object?', 'const copy = obj', 'Object.assign({}, obj)', '{ ...obj }', 'structuredClone(obj)', 'D', 1, 'structuredClone clones nested data (but not functions).'),
(3, 'What does const { a, b } = obj; do?', 'Deletes a and b', 'Destructures properties a and b into variables', 'Compares a and b', 'Creates a new object', 'B', 1, 'Object destructuring extracts values by property name.'),
(3, 'How do you swap two variables using destructuring?', 'a = b; b = a;', '{a, b} = {b, a}', '[a, b] = [b, a]', 'swap(a, b)', 'C', 1, 'Array destructuring swaps without a temp variable.'),
(3, 'What does `Hello ${name}` demonstrate?', 'A template literal', 'A comment', 'A regular string', 'A tagged function', 'A', 1, 'Backticks allow interpolation and multi-line strings.'),
(3, 'What does { name, age } mean when name and age are variables?', 'A destructuring assignment', 'A syntax error', 'A Set', 'Shorthand property names', 'D', 1, 'It is equivalent to { name: name, age: age }.'),
(3, 'What is the difference between for...of and for...in?', 'for...of iterates keys, for...in iterates values', 'for...in works only on arrays', 'They are identical', 'for...of iterates values, for...in iterates keys', 'D', 1, 'Use for...of for arrays and for...in for object keys.'),
(3, 'What does the break statement do inside a loop?', 'Exits the loop immediately', 'Skips to the next iteration', 'Pauses the loop', 'Restarts the loop', 'A', 1, 'continue skips to the next iteration.'),
(3, 'What happens in a switch statement if you forget break?', 'A SyntaxError is thrown', 'The switch stops at the first case', 'Execution falls through to the next case', 'The default case is skipped', 'C', 1, 'Fall-through continues until a break or the end.'),
(3, 'What does "hello".toUpperCase() return?', '"Hello"', '"HELLO"', 'undefined', '"null"', 'B', 1, 'Strings are immutable, so a new string is returned.'),
(3, 'What does "abc".slice(1) return?', '"bc"', '"c"', '"ab"', '"abc"', 'A', 1, 'slice starts at index 1.'),
(3, 'What does "a,b,c".split(",") return?', '["a,b,c"]', '[a, b, c]', '"abc"', '["a", "b", "c"]', 'D', 1, 'split breaks a string into an array.'),
(3, 'What does "banana".replace("a", "o") return?', '"banana"', '"bonana"', '"bnn"', '"bonono"', 'B', 1, 'replace with a string only replaces the first match; use replaceAll for all.'),
(3, 'What does "abc".at(-1) return?', '"a"', 'undefined', '"c"', '"b"', 'C', 1, 'at() accepts negative indexes counting from the end.'),
(3, 'What does parseInt("42px") return?', 'NaN', '"42"', '0', '42', 'D', 1, 'parseInt reads leading digits and stops at the first invalid character.'),
(3, 'What does Number("42px") return?', '"42"', 'NaN', '0', '42', 'B', 1, 'Number is strict and fails on trailing characters.'),
(3, 'What does Number("") return?', 'undefined', '""', '0', 'NaN', 'C', 1, 'An empty string converts to 0.'),
(3, 'What type does (3.14159).toFixed(2) return?', 'A string', 'An object', 'A boolean', 'A number', 'A', 1, 'toFixed returns the string "3.14".'),
(3, 'What does Math.round(2.5) return?', '4', '3', '2.5', '2', 'B', 1, '.5 rounds up toward positive infinity.'),
(3, 'What does Math.floor(-2.5) return?', '-3', '-2', '-2.5', '3', 'A', 1, 'floor rounds toward negative infinity.'),
(3, 'What range does Math.random() return?', '1 up to but not including 0', '0 to 1 inclusive', '1 to 10', '0 up to but not including 1', 'D', 1, 'Multiply and floor it to get integers in a range.'),
(3, 'What does Math.max() return with no arguments?', '0', 'NaN', '-Infinity', 'undefined', 'C', 1, '-Infinity is the identity for max.'),
(3, 'In JavaScript dates, what does getMonth() return for January?', '0', '1', '12', '-1', 'A', 1, 'Months are zero-based, from 0 to 11.'),
(3, 'What does JSON.stringify() do?', 'Parses a JSON string', 'Encrypts data', 'Converts a JavaScript value to a JSON string', 'Validates JSON', 'C', 1, 'JSON.parse does the reverse.'),
(3, 'What happens when JSON.parse receives invalid JSON?', 'It returns undefined', 'It throws a SyntaxError', 'It returns an empty object', 'It returns null', 'B', 1, 'Wrap it in try/catch when input is untrusted.'),
(3, 'What does JSON.stringify do with functions and undefined in an object?', 'They are converted to "null" strings', 'They are kept', 'It throws an error', 'They are omitted', 'D', 1, 'JSON has no function or undefined type.'),
(3, 'What is the output order: console.log(1); setTimeout(() => console.log(2), 0); Promise.resolve().then(() => console.log(3)); console.log(4);', '1 4 2 3', '1 3 4 2', '1 2 3 4', '1 4 3 2', 'D', 1, 'Promise callbacks (microtasks) run before setTimeout callbacks (macrotasks).'),
(3, 'Which best describes JavaScript''s execution model?', 'Compiled only', 'Multi-threaded by default', 'Single-threaded with an event loop', 'Fully parallel', 'C', 1, 'Async work is handled by the browser and queued for the event loop.'),
(3, 'What is the call stack?', 'Browser history', 'A structure that tracks the functions currently being executed', 'A list of loaded scripts', 'A queue of timers', 'B', 1, 'Functions are pushed when called and popped when they return.'),
(3, 'What are the three states of a Promise?', 'Pending, fulfilled, rejected', 'Start, run, end', 'Waiting, done, failed only', 'Open, closed, error', 'A', 1, 'A settled promise is either fulfilled or rejected.');
INSERT INTO questions (exam_id, question, option_a, option_b, option_c, option_d, correct_option, marks, explanation) VALUES
(3, 'What does Promise.all do if one promise rejects?', 'It waits for the others and resolves', 'It rejects immediately', 'It ignores the rejection', 'It retries', 'B', 1, 'Use Promise.allSettled to get every outcome.'),
(3, 'What does Promise.allSettled return?', 'The first resolved value', 'Only the fulfilled values', 'Results of all promises, whether fulfilled or rejected', 'Only errors', 'C', 1, 'It never rejects because of the input promises.'),
(3, 'What does Promise.race do?', 'Waits for all promises', 'Runs promises in sequence', 'Cancels slow promises', 'Settles with the first promise that settles', 'D', 1, 'The first resolve or reject wins.'),
(3, 'What does an async function always return?', 'A Promise', 'undefined', 'The raw return value', 'A callback', 'A', 1, 'Returned values are wrapped in a resolved promise.'),
(3, 'Where can the await keyword be used?', 'Anywhere', 'Only in loops', 'Only in classes', 'Inside async functions (and in ES modules at top level)', 'D', 1, 'Using await in a normal function is a SyntaxError.'),
(3, 'How do you handle errors from await?', 'Use if/else', 'Wrap it in try/catch', 'Use a switch', 'Errors cannot be handled', 'B', 1, 'A rejected promise throws at the await.'),
(3, 'Does fetch() reject on an HTTP 404 response?', 'Only in strict mode', 'Yes, always', 'No, only on network failure; check response.ok', 'Only for 500 errors', 'C', 1, 'A 404 still resolves, so test response.ok or the status.'),
(3, 'What does response.json() return?', 'A Promise that resolves to the parsed data', 'A JSON string', 'The parsed object immediately', 'A boolean', 'A', 1, 'You must await it.'),
(3, 'Which function stops a repeating timer?', 'clearTimeout', 'stopTimer', 'killInterval', 'clearInterval', 'D', 1, 'clearTimeout cancels a setTimeout; clearInterval cancels a setInterval.'),
(3, 'What does document.getElementById("x") return if no element matches?', 'undefined', 'It throws', 'null', 'An empty array', 'C', 1, 'querySelector also returns null when nothing matches.'),
(3, 'What does querySelectorAll return?', 'A single element', 'A static NodeList', 'An HTMLCollection', 'A string', 'B', 1, 'getElementsByClassName returns a live HTMLCollection.'),
(3, 'What is the difference between textContent and innerHTML?', 'innerHTML parses HTML and can introduce XSS', 'innerHTML is read-only', 'They are identical', 'textContent parses HTML', 'A', 1, 'Prefer textContent for user supplied text.'),
(3, 'How do you add a new element to the page?', 'document.write after load', 'createElement, then appendChild', 'element.add()', 'document.insert()', 'B', 1, 'Create the node, set its content, then attach it.'),
(3, 'Which method toggles a class on an element?', 'element.classList.toggle("x")', 'element.className.toggle("x")', 'element.class.toggle("x")', 'element.toggleClass("x")', 'A', 1, 'classList also offers add, remove and contains.'),
(3, 'What is an advantage of addEventListener over onclick?', 'It runs faster', 'It works without a DOM', 'You can attach multiple handlers to one event', 'It is the only way to handle clicks', 'C', 1, 'onclick holds a single handler.'),
(3, 'What is event bubbling?', 'Events are cancelled', 'Events propagate from the root down', 'Events are duplicated', 'Events propagate from the target up through its ancestors', 'D', 1, 'A click on a button also triggers click handlers on its parents.'),
(3, 'What does event.preventDefault() do?', 'Removes the listener', 'Stops all JavaScript', 'Stops the browser''s default action', 'Stops the event bubbling', 'C', 1, 'For example, it stops a form submitting or a link navigating.'),
(3, 'What does event.stopPropagation() do?', 'Stops the event from reaching other elements in the propagation path', 'Deletes the element', 'Removes all listeners', 'Cancels the default action', 'A', 1, 'It prevents bubbling (or capturing) further.'),
(3, 'What is event delegation?', 'Attaching a listener to every child', 'Cancelling child events', 'Delegating tasks to workers', 'Attaching one listener to a parent to handle events from its children', 'D', 1, 'It relies on bubbling and works for dynamically added elements.'),
(3, 'What is the difference between event.target and event.currentTarget?', 'target is the parent', 'target is the element clicked, currentTarget is the element with the listener', 'They are always the same', 'currentTarget is the clicked element', 'B', 1, 'In delegation they usually differ.'),
(3, 'What is debouncing?', 'Cancelling a function', 'Running a function once every interval regardless', 'Delaying a function until activity has stopped for a set time', 'Running a function twice', 'C', 1, 'Common for search boxes and resize handlers.'),
(3, 'What is throttling?', 'Making it async', 'Limiting a function to run at most once per time interval', 'Waiting until the user stops', 'Running it only once forever', 'B', 1, 'Common for scroll handlers.'),
(3, 'When does the DOMContentLoaded event fire?', 'Before the HTML is parsed', 'After all images and styles load', 'When the user clicks', 'When the HTML is fully parsed, without waiting for images', 'D', 1, 'The load event waits for all resources.'),
(3, 'What type of data does localStorage store?', 'Strings', 'Functions', 'Numbers only', 'Any object', 'A', 1, 'Use JSON.stringify and JSON.parse for objects.'),
(3, 'What is a difference between cookies and localStorage?', 'localStorage expires in one day', 'Cookies have unlimited size', 'Cookies are sent with every HTTP request to the server', 'localStorage is sent with every request', 'C', 1, 'Cookies are limited to about 4KB; localStorage allows more.'),
(3, 'What does the constructor method do in a class?', 'Imports a module', 'Initialises a new instance', 'Defines a static method', 'Deletes an instance', 'B', 1, 'It runs when you call new ClassName().'),
(3, 'What must a derived class constructor do before using this?', 'Call new', 'Call bind', 'Return an object', 'Call super()', 'D', 1, 'Otherwise a ReferenceError is thrown.'),
(3, 'What does a static method belong to?', 'The class itself, not instances', 'The prototype chain only', 'Every instance', 'The global object', 'A', 1, 'Call it as ClassName.method().'),
(3, 'What does the # prefix mean in a class field such as #balance?', 'A constant', 'A private field', 'A comment', 'A static field', 'B', 1, 'Private fields are only accessible inside the class.'),
(3, 'What kind of inheritance does JavaScript use?', 'Class-based only', 'None', 'Prototype-based', 'Interface-based', 'C', 1, 'Classes are syntax over prototypes.'),
(3, 'What does typeof class A {} return?', '"object"', '"constructor"', '"class"', '"function"', 'D', 1, 'Classes are special functions.'),
(3, 'What does the new keyword do?', 'Creates an object, links its prototype and runs the constructor', 'Imports a module', 'Declares a variable', 'Copies an object', 'A', 1, 'It also returns the new object (unless the constructor returns another object).'),
(3, 'What does instanceof check?', 'Whether a value is an array only', 'The type of a primitive', 'Whether two objects are equal', 'Whether an object has a constructor''s prototype in its chain', 'D', 1, '[] instanceof Array is true.'),
(3, 'How do you export a default value from an ES module?', 'module.exports = value', 'export default value', 'export = value', 'default export value', 'B', 1, 'module.exports is CommonJS used in Node.js.'),
(3, 'How do you load a script as an ES module in HTML?', '<script import>', '<script es6>', '<script type="module">', '<script module>', 'C', 1, 'Modules are deferred by default and use strict mode.'),
(3, 'What does "use strict" do?', 'Enables stricter parsing and error handling', 'Disables the console', 'Enables new syntax only', 'Makes code run faster', 'A', 1, 'For example, assigning to an undeclared variable throws an error.'),
(3, 'What does the finally block do?', 'Runs whether or not an error occurred', 'Replaces catch', 'Runs only if there is an error', 'Runs only if there is no error', 'A', 1, 'It is used for cleanup.'),
(3, 'How do you throw a custom error?', 'error("message")', 'throw "message" is required', 'throw new Error("message")', 'raise Error("message")', 'C', 1, 'Throwing Error objects gives you a stack trace.'),
(3, 'What is memoization?', 'Deleting unused variables', 'Writing notes in code', 'Compressing memory', 'Caching a function''s results for repeated inputs', 'D', 1, 'It trades memory for speed.'),
(3, 'What is currying?', 'Making a function async', 'Turning f(a, b) into f(a)(b)', 'Merging two functions', 'Calling a function twice', 'B', 1, 'Each call takes one argument and returns a function.');
INSERT INTO questions (exam_id, question, option_a, option_b, option_c, option_d, correct_option, marks, explanation) VALUES
(3, 'What is the main purpose of a Symbol?', 'Creating unique property keys', 'Creating classes', 'Storing text', 'Looping', 'A', 1, 'Every Symbol() value is unique.'),
(3, 'Is JavaScript compiled or interpreted?', 'It is purely interpreted line by line', 'It is compiled ahead of time to machine code only', 'Modern engines use JIT compilation', 'It runs only on servers', 'C', 1, 'Engines such as V8 compile hot code at run time.'),
(3, 'What is the main difference between null and undefined?', 'null means not declared', 'undefined is an object', 'They are identical', 'undefined means no value assigned, null is an intentional empty value', 'D', 1, 'Both are falsy, but they are different types.'),
(3, 'What is the difference between shallow copy and deep copy?', 'A shallow copy is always faster', 'A shallow copy shares nested objects, a deep copy duplicates them', 'They are the same', 'A deep copy shares nested objects', 'B', 1, 'Changing a nested value in a shallow copy affects the original.'),
(3, 'What is Node.js?', 'A CSS tool', 'A JavaScript framework', 'A runtime that runs JavaScript outside the browser', 'A database', 'C', 1, 'It is built on Chrome''s V8 engine.'),
(3, 'What is the difference between a library and a framework?', 'You call a library, but a framework calls your code', 'A library calls your code', 'Frameworks have no structure', 'They are the same', 'A', 1, 'This is called inversion of control.'),
(3, 'What is the purpose of the async attribute versus defer on a script tag?', 'async blocks parsing', 'They are identical', 'defer runs as soon as downloaded', 'async runs as soon as downloaded, defer runs in order after parsing', 'D', 1, 'Both avoid blocking HTML parsing while downloading.');